<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { CalendarPlus, MapPin, Trash2, Trophy } from 'lucide-vue-next'
import type { AdminCompetitionInput, AdminGame, AdminGameInput, AdminGameSetupResponse, AdminGamesResponse, AdminSeasonInput } from '@@/types/admin-club'

definePageMeta({ allowedRoles: ['admin'] })
const selectClass = 'flex min-h-[44px] w-full rounded-lg border border-input bg-surface px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400'
const error = ref<string | null>(null); const success = ref<string | null>(null); const saving = ref(false)
const deletingGameId = ref<string | null>(null)
const season = reactive<AdminSeasonInput>({ name: '', starts_on: '', ends_on: '' })
const competition = reactive<AdminCompetitionInput>({ name: '', season_id: '', type: 'league' })
const venue = reactive({ name: '', address: '', city: '' })
type GameForm = Omit<AdminGameInput, 'matchday' | 'round_label' | 'home_score' | 'away_score' | 'notes'> & {
  matchday: string | number
  round_label: string
  home_score: string | number
  away_score: string | number
  notes: string
}
const game = reactive<GameForm>({ team_id: '', season_id: '', competition_id: null, venue_id: null, opponent_name: '', location_type: 'home', scheduled_at: '', matchday: '', round_label: '', status: 'scheduled', home_score: '', away_score: '', notes: '' })
const { data: setupData, refresh: refreshSetup } = await useFetch<AdminGameSetupResponse>('/api/admin/games/setup', { default: () => ({ seasons: [], competitions: [], venues: [], teams: [] }) })
const { data: gamesData, pending, refresh: refreshGames } = await useFetch<AdminGamesResponse>('/api/admin/games', { default: () => ({ games: [] }) })
const setup = computed(() => setupData.value ?? { seasons: [], competitions: [], venues: [], teams: [] })
const games = computed(() => gamesData.value?.games ?? [])
const activeSeasons = computed(() => setup.value.seasons.filter((item) => item.is_active))
const activeCompetitions = computed(() => setup.value.competitions.filter((item) => item.is_active && item.season_id === game.season_id))
const activeVenues = computed(() => setup.value.venues.filter((item) => item.is_active))
const activeTeams = computed(() => setup.value.teams.filter((item) => item.is_active))
function message(value: string) { success.value = value; error.value = null }
function problem(value: unknown, fallback: string) { const details = value as { data?: { statusMessage?: string }, message?: string }; error.value = details.data?.statusMessage || details.message || fallback; success.value = null }
async function create(path: string, body: object, confirmation: string) { saving.value = true; try { await $fetch(path, { method: 'POST', body }); await refreshSetup(); message(confirmation) } catch (value) { problem(value, 'Unable to save this record.') } finally { saving.value = false } }
async function createSeason() { await create('/api/admin/seasons', { ...season, name: season.name.trim() }, 'Season created.'); season.name = ''; season.starts_on = ''; season.ends_on = '' }
async function createCompetition() { await create('/api/admin/competitions', { ...competition, name: competition.name.trim() }, 'Competition created.'); competition.name = '' }
async function createVenue() { await create('/api/admin/venues', { ...venue, name: venue.name.trim(), address: venue.address.trim() || null, city: venue.city.trim() || null }, 'Venue created.'); venue.name = ''; venue.address = ''; venue.city = '' }
async function createGame() { saving.value = true; try { await $fetch('/api/admin/games', { method: 'POST', body: { ...game, opponent_name: game.opponent_name.trim(), scheduled_at: new Date(game.scheduled_at).toISOString(), matchday: game.matchday === '' ? null : game.matchday, round_label: game.round_label.trim() || null, home_score: game.home_score === '' ? null : game.home_score, away_score: game.away_score === '' ? null : game.away_score, notes: game.notes.trim() || null } }); await refreshGames(); message('Game created.'); game.opponent_name = ''; game.scheduled_at = ''; game.matchday = ''; game.round_label = ''; game.home_score = ''; game.away_score = ''; game.notes = '' } catch (value) { problem(value, 'Unable to create game.') } finally { saving.value = false } }
async function deleteGame(item: AdminGame) {
  if (!window.confirm(`Delete ${item.team.name} vs ${item.opponent_name}? Its squad and attendance records will also be deleted.`)) return
  deletingGameId.value = item.id
  try { await $fetch(`/api/admin/games/${item.id}`, { method: 'DELETE' } as never); await refreshGames(); message('Game deleted.') }
  catch (value) { problem(value, 'Unable to delete the game.') }
  finally { deletingGameId.value = null }
}
watch(activeSeasons, (items) => { if (!game.season_id && items[0]) game.season_id = items[0].id; if (!competition.season_id && items[0]) competition.season_id = items[0].id }, { immediate: true })
watch(activeTeams, (items) => { if (!game.team_id && items[0]) game.team_id = items[0].id }, { immediate: true })
watch(activeVenues, (items) => { if (!game.venue_id && items[0]) game.venue_id = items[0].id }, { immediate: true })
watch(() => game.season_id, () => { if (!activeCompetitions.value.some((item) => item.id === game.competition_id)) game.competition_id = null })
function formattedDate(value: string) { return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) }
</script>

<template>
  <div class="mx-auto max-w-7xl space-y-6"><div class="space-y-2"><p class="eyebrow text-brand-700">Admin area</p><h1>Games</h1><p class="max-w-2xl text-body text-[color:var(--color-text-secondary)]">Set up club competitions and venues, then schedule upcoming or record completed games.</p></div>
    <div v-if="success" class="rounded-lg border border-[color:var(--status-confirmed-ring)] bg-[var(--status-confirmed-bg)] px-4 py-3 text-sm text-[var(--status-confirmed-text)]">{{ success }}</div><div v-if="error" class="rounded-lg border border-[color:var(--status-declined-ring)] bg-[var(--status-declined-bg)] px-4 py-3 text-sm text-[var(--status-declined-text)]">{{ error }}</div>
    <div class="grid gap-6 xl:grid-cols-[minmax(0,1.4fr)_minmax(320px,0.9fr)]"><div class="space-y-6"><Card class="space-y-5"><div class="flex items-center gap-3"><CalendarPlus class="h-5 w-5 text-brand-700" /><div><h2>Create game</h2><p class="text-label text-[color:var(--color-text-secondary)]">Competition and venue are optional for friendlies.</p></div></div><form class="grid gap-4 md:grid-cols-2" @submit.prevent="createGame"><div><Label for="game-team">Sporting team</Label><select id="game-team" v-model="game.team_id" :class="selectClass" required><option value="" disabled>Select team</option><option v-for="item in activeTeams" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="game-season">Season</Label><select id="game-season" v-model="game.season_id" :class="selectClass" required><option value="" disabled>Select season</option><option v-for="item in activeSeasons" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="opponent">Opponent</Label><Input id="opponent" v-model="game.opponent_name" placeholder="Opponent name" required /></div><div><Label for="kickoff">Kickoff</Label><Input id="kickoff" v-model="game.scheduled_at" type="datetime-local" required /></div><div><Label for="game-competition">Competition</Label><select id="game-competition" v-model="game.competition_id" :class="selectClass"><option :value="null">Friendly / no competition</option><option v-for="item in activeCompetitions" :key="item.id" :value="item.id">{{ item.name }} ({{ item.type }})</option></select></div><div><Label for="game-venue">Venue</Label><select id="game-venue" v-model="game.venue_id" :class="selectClass"><option :value="null">Venue to be confirmed</option><option v-for="item in activeVenues" :key="item.id" :value="item.id">{{ item.name }}{{ item.city ? ` · ${item.city}` : '' }}</option></select></div><div><Label for="location">Location</Label><select id="location" v-model="game.location_type" :class="selectClass"><option value="home">Home</option><option value="away">Away</option><option value="neutral">Neutral</option></select></div><div><Label for="matchday">Matchday</Label><Input id="matchday" v-model="game.matchday" type="number" min="1" placeholder="e.g. 1" /></div><div><Label for="round">Round</Label><Input id="round" v-model="game.round_label" placeholder="e.g. Quarter-final" /></div><div><Label for="game-status">Status</Label><select id="game-status" v-model="game.status" :class="selectClass"><option value="scheduled">Scheduled</option><option value="completed">Completed</option><option value="postponed">Postponed</option><option value="cancelled">Cancelled</option></select></div><template v-if="game.status === 'completed'"><div><Label for="home-score">Home score</Label><Input id="home-score" v-model="game.home_score" type="number" min="0" required /></div><div><Label for="away-score">Away score</Label><Input id="away-score" v-model="game.away_score" type="number" min="0" required /></div></template><div class="md:col-span-2"><Label for="game-notes">Notes</Label><textarea id="game-notes" v-model="game.notes" class="min-h-[88px] w-full rounded-lg border border-input bg-surface px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400" placeholder="Optional match details" /></div><Button type="submit" class="gap-2 md:col-span-2" :disabled="saving || !activeTeams.length || !activeSeasons.length"><Trophy class="h-4 w-4" />{{ saving ? 'Saving...' : 'Create game' }}</Button></form></Card>
        <Card class="overflow-hidden p-0"><div class="border-b border-border px-4 py-4"><h2>Games</h2><p class="mt-1 text-label text-[color:var(--color-text-secondary)]">Most recent 100 games</p></div><div v-if="pending" class="px-4 py-8 text-center text-sm text-[color:var(--color-text-secondary)]">Loading games...</div><div v-else-if="!games.length" class="px-4 py-8 text-center text-sm text-[color:var(--color-text-secondary)]">No games have been created yet.</div><div v-for="item in games" :key="item.id" class="flex items-center gap-3 border-b border-border px-4 py-4 last:border-b-0"><NuxtLink :to="`/admin/games/${item.id}`" class="min-w-0 flex-1 hover:text-brand-700"><div class="flex flex-wrap items-center justify-between gap-2"><p class="font-medium">{{ item.team.name }} vs {{ item.opponent_name }}</p><Badge :status="item.status === 'completed' ? 'confirmed' : item.status === 'cancelled' ? 'declined' : 'pending'">{{ item.status }}</Badge></div><p class="mt-1 text-sm text-[color:var(--color-text-secondary)]">{{ formattedDate(item.scheduled_at) }} · {{ item.location_type }}{{ item.matchday ? ` · Matchday ${item.matchday}` : '' }}</p><p class="text-label text-[color:var(--color-text-secondary)]">{{ item.season.name }}{{ item.competition ? ` · ${item.competition.name}` : '' }}{{ item.venue ? ` · ${item.venue.name}` : '' }}{{ item.status === 'completed' ? ` · ${item.home_score}–${item.away_score}` : '' }}</p></NuxtLink><div class="flex shrink-0 gap-2"><NuxtLink :to="`/coach/games/${item.id}`" class="rounded-lg border border-input px-3 py-2 text-sm hover:bg-brand-50">Coach view</NuxtLink><Button variant="destructive" size="sm" class="gap-2" :disabled="deletingGameId === item.id" @click="deleteGame(item)"><Trash2 class="h-4 w-4" />{{ deletingGameId === item.id ? 'Deleting...' : 'Delete' }}</Button></div></div></Card></div>
      <div class="space-y-6"><Card class="space-y-4"><h2>Create season</h2><form class="space-y-3" @submit.prevent="createSeason"><div><Label for="season-name">Name</Label><Input id="season-name" v-model="season.name" placeholder="2026/2027" required /></div><div class="grid grid-cols-2 gap-3"><div><Label for="season-start">Starts</Label><Input id="season-start" v-model="season.starts_on" type="date" required /></div><div><Label for="season-end">Ends</Label><Input id="season-end" v-model="season.ends_on" type="date" required /></div></div><Button type="submit" variant="outline" class="w-full" :disabled="saving">Create season</Button></form></Card><Card class="space-y-4"><h2>Create competition</h2><form class="space-y-3" @submit.prevent="createCompetition"><div><Label for="competition-name">Name</Label><Input id="competition-name" v-model="competition.name" placeholder="PZPN" required /></div><div><Label for="competition-season">Season</Label><select id="competition-season" v-model="competition.season_id" :class="selectClass" required><option v-for="item in activeSeasons" :key="item.id" :value="item.id">{{ item.name }}</option></select></div><div><Label for="competition-type">Type</Label><select id="competition-type" v-model="competition.type" :class="selectClass"><option value="league">League</option><option value="cup">Cup</option><option value="friendly">Friendly</option><option value="tournament">Tournament</option></select></div><Button type="submit" variant="outline" class="w-full" :disabled="saving || !activeSeasons.length">Create competition</Button></form></Card><Card class="space-y-4"><div class="flex items-center gap-2"><MapPin class="h-5 w-5 text-brand-700" /><h2>Create venue</h2></div><form class="space-y-3" @submit.prevent="createVenue"><div><Label for="venue-name">Venue name</Label><Input id="venue-name" v-model="venue.name" placeholder="Stadion Olimpijski" required /></div><div><Label for="venue-city">City</Label><Input id="venue-city" v-model="venue.city" placeholder="Wrocław" /></div><div><Label for="venue-address">Address</Label><Input id="venue-address" v-model="venue.address" placeholder="Optional address" /></div><Button type="submit" variant="outline" class="w-full" :disabled="saving">Create venue</Button></form></Card></div>
    </div>
  </div>
</template>
